package com.guocheng.mediapocket;
import android.app.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
final class SourceSearchClient {
 static JSONArray run(Activity a,FusionCatalog.Session session,String title,long budget)throws Exception{long deadline=System.nanoTime()+TimeUnit.MILLISECONDS.toNanos(budget);LinkedHashMap<String,JSONObject> found=new LinkedHashMap<>();Exception last=null;int responses=0;for(String keyword:SourceSearchRules.keywords(title)){long left=TimeUnit.NANOSECONDS.toMillis(deadline-System.nanoTime());if(left<=0)break;try{JSONObject result=PlaybackSitePicker.request(a,session,"search",keyword,"",1,Math.min(35000,left));JSONArray list=result.optJSONArray("list");int count=list==null?0:list.length();responses++;record(a,session.site.optString("name"),keyword,"返回 "+count+" 条");for(int i=0;list!=null&&i<Math.min(200,list.length());i++){JSONObject item=list.optJSONObject(i);if(item!=null&&!item.optString("vod_id").isEmpty())found.putIfAbsent(item.optString("vod_id"),item);}if(!found.isEmpty())break;}catch(Exception e){last=e;record(a,session.site.optString("name"),keyword,"请求失败 · "+reason(e));}}if(found.isEmpty()&&responses==0&&last!=null)throw last;JSONArray out=new JSONArray();for(JSONObject item:found.values())out.put(item);return out;}
 static String reason(Throwable e){StringBuilder out=new StringBuilder();for(int i=0;e!=null&&i<3;i++,e=e.getCause()){if(i>0)out.append(" → ");out.append(e.getClass().getSimpleName());String msg=e.getMessage();if(msg!=null)out.append(": ").append(msg.replaceAll("(?i)https?://[^\\s]+","[地址]").replaceAll("[\\r\\n]+"," "));}return out.length()>240?out.substring(0,240):out.toString();}
 static synchronized void record(Activity a,String site,String word,String result){try{String line=site+" · 关键词「"+word+"」 · "+result;JSONArray old=new JSONArray(a.getSharedPreferences("data",0).getString("sourceSearchReport","[]")),next=new JSONArray().put(line);for(int i=0;i<Math.min(39,old.length());i++)next.put(old.optString(i));a.getSharedPreferences("data",0).edit().putString("sourceSearchReport",next.toString()).apply();}catch(Exception ignored){}}
 static String report(Activity a){try{JSONArray lines=new JSONArray(a.getSharedPreferences("data",0).getString("sourceSearchReport","[]"));StringBuilder out=new StringBuilder();for(int i=0;i<lines.length();i++)out.append(lines.optString(i)).append('\n');return out.length()==0?"尚未查询其他站点。":out.toString();}catch(Exception e){return "暂无记录";}}
}
